INSERT INTO _migration_476_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_ecology_s2_014', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student studies the nitrogen cycle in the soil of a maize farm in northern Ghana.', 'structured', NULL, NULL, '(a) The conversion of inert atmospheric nitrogen gas (N₂) into ammonia or ammonium compounds that plants can use (1); carried out by nitrogen-fixing bacteria such as Rhizobium in legume root nodules and free-living bacteria such as Azotobacter, or industrially in the Haber process (1). (b) The process is nitrification (1): Nitrosomonas oxidises ammonium ions to nitrite ions (1); Nitrobacter then oxidises nitrite ions to nitrate ions (1). Accept a correct two-step description without genus names for a maximum of 2 marks. (c) Waterlogging fills the soil air spaces with water, so conditions become anaerobic (1); denitrifying bacteria such as Pseudomonas then use nitrate in place of oxygen for respiration and convert it to nitrogen gas, which escapes to the atmosphere — denitrification (1).', '(a) The conversion of inert atmospheric nitrogen gas (N₂) into ammonia or ammonium compounds that plants can use (1); carried out by nitrogen-fixing bacteria such as Rhizobium in legume root nodules and free-living bacteria such as Azotobacter, or industrially in the Haber process (1). (b) The process is nitrification (1): Nitrosomonas oxidises ammonium ions to nitrite ions (1); Nitrobacter then oxidises nitrite ions to nitrate ions (1). Accept a correct two-step description without genus names for a maximum of 2 marks. (c) Waterlogging fills the soil air spaces with water, so conditions become anaerobic (1); denitrifying bacteria such as Pseudomonas then use nitrate in place of oxygen for respiration and convert it to nitrogen gas, which escapes to the atmosphere — denitrification (1).', 'medium', '7', '7', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_015', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Fertiliser is washed from fields into a lake near an intensive poultry farm.', 'structured', NULL, NULL, '(a) The enrichment of a body of water with nutrients, especially nitrate and phosphate ions (1), leading to excessive growth of producers such as algae (1). (b) The algae multiply until they block light, so submerged plants and deeper algae die (1); decomposer (saprotrophic) bacteria multiply as they break down the dead organic matter (1); the bacteria respire aerobically and remove dissolved oxygen from the water, raising the biological oxygen demand (1); fish and other aerobic animals suffocate and die from the lack of dissolved oxygen (1). (c) Any one of: applying fertiliser only at recommended rates and times, and not just before heavy rain; using slow-release organic manure instead of soluble inorganic fertiliser; planting vegetated buffer strips along the lake edge; fencing livestock away from the water (1).', '(a) The enrichment of a body of water with nutrients, especially nitrate and phosphate ions (1), leading to excessive growth of producers such as algae (1). (b) The algae multiply until they block light, so submerged plants and deeper algae die (1); decomposer (saprotrophic) bacteria multiply as they break down the dead organic matter (1); the bacteria respire aerobically and remove dissolved oxygen from the water, raising the biological oxygen demand (1); fish and other aerobic animals suffocate and die from the lack of dissolved oxygen (1). (c) Any one of: applying fertiliser only at recommended rates and times, and not just before heavy rain; using slow-release organic manure instead of soluble inorganic fertiliser; planting vegetated buffer strips along the lake edge; fencing livestock away from the water (1).', 'medium', '7', '7', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_016', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student investigates energy flow through a savanna grassland ecosystem.', 'structured', NULL, NULL, '(a) Gross primary productivity (GPP) is the total rate at which producers convert light energy into chemical energy in photosynthesis (1); net primary productivity (NPP) is GPP minus the energy the producers lose in respiration (NPP = GPP − R), the energy available for growth and for transfer to consumers (1). (b) Only about 10% of the energy at each level is transferred to the next (1); energy is lost as heat in respiration, in excretory products and in uneaten or undigested material (1); so after four or five transfers too little energy remains to support a viable breeding population of top consumers (1). (c) A pyramid of energy shows the rate of energy flow through each trophic level over a fixed period (1); because energy is always lost between levels and cannot flow back from consumers to producers, each successive level receives less energy, so the bars must always decrease upwards (1).', '(a) Gross primary productivity (GPP) is the total rate at which producers convert light energy into chemical energy in photosynthesis (1); net primary productivity (NPP) is GPP minus the energy the producers lose in respiration (NPP = GPP − R), the energy available for growth and for transfer to consumers (1). (b) Only about 10% of the energy at each level is transferred to the next (1); energy is lost as heat in respiration, in excretory products and in uneaten or undigested material (1); so after four or five transfers too little energy remains to support a viable breeding population of top consumers (1). (c) A pyramid of energy shows the rate of energy flow through each trophic level over a fixed period (1); because energy is always lost between levels and cannot flow back from consumers to producers, each successive level receives less energy, so the bars must always decrease upwards (1).', 'hard', '7', '7', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_476_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_ecology_s2_014_a', 'q_albio_ecology_s2_014', 'a', 'State what is meant by nitrogen fixation.', '2', 'The conversion of inert atmospheric nitrogen gas (N₂) into ammonia or ammonium compounds that plants can use (1); carried out by nitrogen-fixing bacteria such as Rhizobium in legume root nodules and free-living bacteria such as Azotobacter, or industrially in the Haber process (1).', '1'),
('sqp_q_albio_ecology_s2_014_b', 'q_albio_ecology_s2_014', 'b', 'Describe how ammonium ions in the soil are converted into nitrate ions that the maize plants can absorb, naming the bacteria involved.', '3', 'The process is nitrification (1): Nitrosomonas oxidises ammonium ions to nitrite ions (1); Nitrobacter then oxidises nitrite ions to nitrate ions (1). Accept a correct two-step description without genus names for a maximum of 2 marks.', '2'),
('sqp_q_albio_ecology_s2_014_c', 'q_albio_ecology_s2_014', 'c', 'The field becomes waterlogged after heavy rain. Explain why the concentration of nitrate ions in the waterlogged soil falls.', '2', 'Waterlogging fills the soil air spaces with water, so conditions become anaerobic (1); denitrifying bacteria such as Pseudomonas then use nitrate in place of oxygen for respiration and convert it to nitrogen gas, which escapes to the atmosphere — denitrification (1).', '3'),
('sqp_q_albio_ecology_s2_015_a', 'q_albio_ecology_s2_015', 'a', 'State what is meant by eutrophication.', '2', 'The enrichment of a body of water with nutrients, especially nitrate and phosphate ions (1), leading to excessive growth of producers such as algae (1).', '1'),
('sqp_q_albio_ecology_s2_015_b', 'q_albio_ecology_s2_015', 'b', 'Describe the sequence of events that links the algal bloom to the death of fish in the lake.', '4', 'The algae multiply until they block light, so submerged plants and deeper algae die (1); decomposer (saprotrophic) bacteria multiply as they break down the dead organic matter (1); the bacteria respire aerobically and remove dissolved oxygen from the water, raising the biological oxygen demand (1); fish and other aerobic animals suffocate and die from the lack of dissolved oxygen (1).', '2'),
('sqp_q_albio_ecology_s2_015_c', 'q_albio_ecology_s2_015', 'c', 'Suggest one farming practice that would reduce the nutrient run-off responsible for eutrophication.', '1', 'Any one of: applying fertiliser only at recommended rates and times, and not just before heavy rain; using slow-release organic manure instead of soluble inorganic fertiliser; planting vegetated buffer strips along the lake edge; fencing livestock away from the water (1).', '3'),
('sqp_q_albio_ecology_s2_016_a', 'q_albio_ecology_s2_016', 'a', 'Distinguish between gross primary productivity and net primary productivity.', '2', 'Gross primary productivity (GPP) is the total rate at which producers convert light energy into chemical energy in photosynthesis (1); net primary productivity (NPP) is GPP minus the energy the producers lose in respiration (NPP = GPP − R), the energy available for growth and for transfer to consumers (1).', '1'),
('sqp_q_albio_ecology_s2_016_b', 'q_albio_ecology_s2_016', 'b', 'Explain why food chains rarely have more than four or five trophic levels.', '3', 'Only about 10% of the energy at each level is transferred to the next (1); energy is lost as heat in respiration, in excretory products and in uneaten or undigested material (1); so after four or five transfers too little energy remains to support a viable breeding population of top consumers (1).', '2'),
('sqp_q_albio_ecology_s2_016_c', 'q_albio_ecology_s2_016', 'c', 'Explain why a pyramid of energy for an ecosystem is never inverted.', '2', 'A pyramid of energy shows the rate of energy flow through each trophic level over a fixed period (1); because energy is always lost between levels and cannot flow back from consumers to producers, each successive level receives less energy, so the bars must always decrease upwards (1).', '3');
INSERT INTO _migration_476_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_476_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_476_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_476_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_476_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_476_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_476_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_476_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_476_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 3 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_476_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 3 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_476_expected e ON e.id = q.id) = 3 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_476_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 9 THEN 1 ELSE 0 END;
